const collectionMemberEndpoints = {
	"/v1/body_measurements": "/v1/body_measurements/:date",
	"/v1/exercise_templates": "/v1/exercise_templates/:exerciseTemplateId",
	"/v1/routine_folders": "/v1/routine_folders/:folderId",
	"/v1/routines": "/v1/routines/:routineId",
	"/v1/workouts": "/v1/workouts/:workoutId",
	"/v1/workouts/events": undefined,
} as const satisfies Record<
	ReadCollectionEndpoint,
	ReadMemberEndpoint | undefined
>;

function errorIdentity(error: ReadOperationError):
	| {
			readonly status?: number;
			readonly method: string;
			readonly endpoint: string;
	  }
	| undefined {
	if (isHevyHttpError(error) || error instanceof NotFoundError) {
		return {
			status: error.status,
			method: error.method,
			endpoint: error.endpoint,
		};
	}
	return undefined;
}

/**
 * Classify only the documented read-side 404 cases.
 *
 * Matching is based on the tagged error's HTTP identity and the operation's
 * endpoint identity. It deliberately does not inspect messages or mutable
 * request state, so unexpected errors remain in the Effect channel.
 */
export function classifyReadError(
	error: ReadOperationError,
	endpoint: ReadEndpoint,
	page?: number,
): ExpectedReadError | undefined {
	const identity = errorIdentity(error);
	if (
		identity === undefined ||
		identity.status !== 404 ||
		identity.method.toUpperCase() !== "GET"
	) {
		return undefined;
	}

	const canonicalError = canonicalEndpointIdentity(identity.endpoint);
	const canonicalOperation = canonicalEndpointIdentity(endpoint);
	if (page !== undefined) {
		if (
			page > 1 &&
			canonicalOperation in collectionMemberEndpoints &&
			canonicalError === canonicalOperation
		) {
			return "end_of_list";
		}
		return undefined;
	}

	if (
		canonicalOperation in collectionMemberEndpoints &&
		canonicalError ===
			collectionMemberEndpoints[canonicalOperation as ReadCollectionEndpoint]
	) {
		return "not_found";
	}
	if (canonicalOperation === canonicalError) {
		const memberEndpoint = canonicalOperation as ReadMemberEndpoint;
		if (
			memberEndpoint === "/v1/body_measurements/:date" ||
			memberEndpoint === "/v1/exercise_templates/:exerciseTemplateId" ||
			memberEndpoint === "/v1/routine_folders/:folderId" ||
			memberEndpoint === "/v1/routines/:routineId" ||
			memberEndpoint === "/v1/workouts/:workoutId"
		) {
			return "not_found";
		}
	}
	return undefined;
}

export function isExpectedReadNotFound(
	error: ReadOperationError,
	endpoint: ReadEndpoint,
): boolean {
	return classifyReadError(error, endpoint) === "not_found";
}

export function isExpectedReadEndOfList(
	error: ReadOperationError,
	endpoint: ReadCollectionEndpoint,
	page: number,
): boolean {
	return page > 1 && classifyReadError(error, endpoint, page) === "end_of_list";
}

import type {
	HevyClient,
	HevyCommitState,
	HevyExecutionOutcome,
	HevyOperationSafety,
	HevyRequestOptions,
	HevyRequestPhase,
} from "@hevy-mcp/hevy-client";
import { Cause, Clock, Effect, Exit } from "effect";
import {
	isFunction,
	isString,
	type RuntimeValue,
} from "./utils/type-predicates.js";
import { logCoreError } from "./utils/core-logger.js";
import { createSafeErrorDiagnostic } from "./utils/error-policy.js";

/** Per-request control supplied by MCP, HTTP, CLI, or a lifecycle owner. */
export interface ToolExecutionContext extends HevyRequestOptions {
	readonly requestId?: string;
}

/** Safe, adapter-neutral execution metadata used in every structured error. */
export interface StructuredExecutionProjection {
	readonly outcome: HevyExecutionOutcome;
	readonly phase: HevyRequestPhase;
	readonly operation_safety: HevyOperationSafety;
	readonly commit_state: HevyCommitState;
	readonly safe_to_retry: boolean;
	readonly code?: string;
	readonly status?: number;
}

/** Backward-compatible name for the structured error projection. */
export type StructuredExecutionError = StructuredExecutionProjection;
type MutableExecutionProjection = {
	-readonly [
		K in keyof StructuredExecutionProjection
	]?: StructuredExecutionProjection[K];
} & Pick<
	StructuredExecutionProjection,
	"outcome" | "phase" | "operation_safety" | "commit_state" | "safe_to_retry"
>;

export type ExecutionProjectionSource = Partial<
	Pick<
		StructuredExecutionProjection,
		| "outcome"
		| "phase"
		| "operation_safety"
		| "commit_state"
		| "safe_to_retry"
		| "code"
		| "status"
	>
>;

export function createExecutionProjection(
	source?: ExecutionProjectionSource,
): StructuredExecutionProjection {
	const projection: MutableExecutionProjection = {
		outcome: source?.outcome ?? "terminal_failure",
		phase: source?.phase ?? "before-dispatch",
		operation_safety: source?.operation_safety ?? "read",
		commit_state: source?.commit_state ?? "not_sent",
		safe_to_retry: source?.safe_to_retry ?? false,
	};
	if (source?.code) projection.code = source.code;
	if (source?.status !== undefined) projection.status = source.status;
	return projection;
}

export function mergeAbortSignals(
	...signals: Array<AbortSignal | undefined>
): AbortSignal | undefined {
	const active = signals.filter(
		(signal): signal is AbortSignal => signal !== undefined,
	);
	if (active.length === 0) return undefined;
	if (active.length === 1) return active[0];
	// Node 24 and the supported Worker runtimes provide AbortSignal.any. The
	// native composition owns listener cleanup when the derived signal settles,
	// avoiding one retained lifecycle/request listener per invocation. Older
	// self-hosted Node runtimes (< 20.3) lack it; the TypeError from the missing
	// static falls through to manual composition instead of failing dispatch.
	try {
		return AbortSignal.any(active);
	} catch (error) {
		if (!(error instanceof TypeError)) throw error;
	}
	const composed = new AbortController();
	const listeners: Array<{
		signal: AbortSignal;
		onAbort: () => void;
	}> = [];
	const abort = (signal: AbortSignal) => {
		for (const listener of listeners) {
			listener.signal.removeEventListener("abort", listener.onAbort);
		}
		listeners.length = 0;
		composed.abort(signal.reason);
	};
	for (const signal of active) {
		if (signal.aborted) {
			abort(signal);
			break;
		}
		const onAbort = () => abort(signal);
		listeners.push({ signal, onAbort });
		signal.addEventListener("abort", onAbort, { once: true });
	}
	return composed.signal;
}

function defectMessage(defect: RuntimeValue): string {
	if (defect instanceof Error) {
		return defect.message;
	}
	if (isString(defect)) {
		return defect;
	}
	try {
		return JSON.stringify(defect) ?? "Unknown defect";
	} catch {
		return "Unknown defect";
	}
}

/**
 * Run one MCP operation with the request's remaining budget.
 *
 * The timeout is deliberately calculated inside the Effect runtime so tests
 * can provide TestClock and callers cannot bypass an absolute deadline by
 * omitting `forExecution` from a handler.
 */
export async function runBoundedExecution<A, E>(
	effect: Effect.Effect<A, E>,
	options: {
		readonly signal?: AbortSignal;
		readonly timeoutMs: number;
		readonly deadline?: number;
	},
): Promise<A> {
	const bounded = Effect.gen(function* () {
		const now = yield* Clock.currentTimeMillis;
		const deadline = options.deadline ?? now + options.timeoutMs;
		const remaining = Math.max(0, deadline - now);
		return yield* Effect.timeout(effect, remaining);
	});
	const exit = await Effect.runPromiseExit(bounded, {
		signal: options.signal,
	});
	if (Exit.isSuccess(exit)) return exit.value;
	const failure = exit.cause.reasons.find(Cause.isFailReason)?.error;
	if (failure !== undefined) throw failure;
	if (Cause.hasInterruptsOnly(exit.cause)) {
		throw new DOMException(
			"The request was canceled by the client.",
			"AbortError",
		);
	}
	const dieReason = exit.cause.reasons.find(Cause.isDieReason);
	if (dieReason !== undefined) {
		const message = defectMessage(dieReason.defect);
		// Bounded diagnostic (category/status/frames only), never the raw defect
		// message, matching the core logging policy for tool errors.
		logCoreError(
			"Unexpected execution defect",
			createSafeErrorDiagnostic(dieReason.defect),
		);
		if (dieReason.defect instanceof Error) {
			throw dieReason.defect;
		}
		throw new Error(message);
	}
	throw new Error("The request failed unexpectedly.");
}

type ClientMethod = keyof HevyClient;

/**
 * The curated client's options slot is deliberately explicit. Inferring it
 * from the final argument is unsafe because IDs and request payloads are also
 * objects/strings and most generated wrappers silently ignore extra args.
 */
/** Canonical options-slot metadata shared by binding and table-driven tests. */
export const HEVY_CLIENT_OPTION_INDEXES = {
	getWorkouts: 1,
	getWorkout: 1,
	createWorkout: 1,
	updateWorkout: 2,
	getWorkoutCount: 0,
	getWorkoutEvents: 1,
	getRoutines: 1,
	getRoutineById: 1,
	createRoutine: 1,
	updateRoutine: 2,
	getExerciseTemplates: 1,
	getExerciseTemplate: 1,
	getExerciseHistory: 2,
	createExerciseTemplate: 1,
	getRoutineFolders: 1,
	createRoutineFolder: 1,
	getRoutineFolder: 1,
	getBodyMeasurements: 1,
	getBodyMeasurement: 1,
	createBodyMeasurement: 1,
	updateBodyMeasurement: 2,
	getUserInfo: 0,
} satisfies Record<ClientMethod, number>;

/**
 * Bind one immutable control object to every curated client operation. A
 * proxy keeps existing tool code source-compatible while making it impossible
 * for one page of a workflow to silently lose cancellation/deadline state.
 */
export function bindClientExecution<TClient extends HevyClient>(
	client: TClient,
	control: ToolExecutionContext,
): TClient {
	return new Proxy(client, {
		get(target, property, receiver) {
			const value = Reflect.get(target, property, receiver);
			if (!isFunction(value)) return value;
			// Proxy invariant: a non-configurable, non-writable own data
			// property must be reported verbatim. The hidden native request
			// Effect seam is defined exactly that way; returning a bound or
			// options-binding copy would fabricate a new function value and
			// throw a TypeError when operations recover the seam through
			// this proxy.
			const descriptor = Reflect.getOwnPropertyDescriptor(target, property);
			if (
				descriptor !== undefined &&
				descriptor.configurable === false &&
				descriptor.writable === false
			) {
				return value;
			}
			const optionIndex =
				property in HEVY_CLIENT_OPTION_INDEXES
					? HEVY_CLIENT_OPTION_INDEXES[property as ClientMethod]
					: undefined;
			if (optionIndex === undefined) {
				return value.bind(target);
			}
			return (...args: unknown[]) => {
				const provided = args[optionIndex] as HevyRequestOptions | undefined;
				const merged: HevyRequestOptions = {
					...provided,
					...control,
				};
				args[optionIndex] = merged;
				return Reflect.apply(value, target, args);
			};
		},
	}) as TClient;
}

import type { McpServer, ToolAnnotations } from "@modelcontextprotocol/server";
import { Effect } from "effect";
import { z } from "zod";
import { ClientNotInitializedError } from "../effect-errors.js";
import { HevyOperationsService } from "../effect-services.js";
import { respond, type ResponseContract } from "../utils/response-contracts.js";
import { compactJsonSchema } from "../utils/compact-json-schema.js";
import type { InferToolParams } from "../utils/tool-helpers.js";
import type { ToolTelemetryMetadata } from "../utils/tool-taxonomy.js";
import type { ToolRuntime } from "./tool-runtime.js";
import type { ToolExecutionContext } from "../execution.js";
import {
	ToolInputValidationError,
	type CoreToolError,
} from "../effect-errors.js";
import { normalizeCoreCause } from "./operation-helpers.js";

type ToolDefinitionBase<
	TSchema extends Record<string, z.ZodTypeAny>,
	TResult,
> = Pick<ToolTelemetryMetadata, "feature" | "operation"> & {
	readonly name: string;
	readonly description: string;
	readonly inputSchema: TSchema;
	readonly annotations: ToolAnnotations;
	readonly responseContract: ResponseContract<TResult>;
	execute(
		runtime: ToolRuntime,
		args: InferToolParams<TSchema>,
	): Effect.Effect<TResult, CoreToolError, never>;
};

type RegisteredToolConfig = {
	description: string;
	inputSchema: ReturnType<typeof compactJsonSchema>;
	annotations: ToolAnnotations;
	outputSchema?: ReturnType<typeof compactJsonSchema>;
};

export type ToolRegistrar = Pick<McpServer, "registerTool">;

export type ToolDefinition<
	TSchema extends Record<string, z.ZodTypeAny>,
	TResult,
> = ToolDefinitionBase<TSchema, TResult> &
	(
		| {
				readonly kind: "read";
				readonly outputSchema: z.ZodRawShape;
		  }
		| {
				readonly kind: "write";
				readonly outputSchema?: z.ZodRawShape;
		  }
	);

type ToolDefinitionMetadata = {
	readonly name: string;
	readonly description: string;
	readonly inputSchema: Record<string, z.ZodTypeAny>;
	readonly annotations: ToolAnnotations;
	readonly outputSchema?: z.ZodRawShape;
};
type RegistrationArgs = z.output<z.ZodObject<Record<string, z.ZodTypeAny>>>;

type UntypedToolDefinition = ToolDefinitionMetadata &
	Pick<ToolTelemetryMetadata, "feature" | "operation"> & {
		readonly kind: "read" | "write";
		readonly responseContract: ResponseContract<unknown>;
		execute(
			runtime: ToolRuntime,
			args: RegistrationArgs,
		): Effect.Effect<unknown, CoreToolError, never>;
	};

/**
 * One-time-per-isolate registration metadata for each tool definition.
 *
 * Building a tool's compact JSON Schema (and the SDK's eager wire conversion
 * of the `compactJsonSchema`-wrapped schema on registration) is the dominant
 * CPU cost when constructing an MCP server. Tool definitions are module-level
 * constants, so this metadata can be computed once and shared by every server
 * a single isolate builds. The SDK's `registerTool` reads the schema strictly
 * through the Standard Schema interface and never mutates it, so sharing the
 * memoized config across concurrent servers is safe.
 *
 * Keep the memo lazy: CLI and test processes that never build a Hevy server
 * pay nothing. Isolate-based edge runtimes that want the one-time conversion
 * moved into module-scope (outside request CPU) call `preloadHevyToolSchemas`.
 */
const registeredToolConfigCache = new WeakMap<
	ToolDefinitionMetadata,
	RegisteredToolConfig
>();

export function getRegisteredToolConfig(
	definition: ToolDefinitionMetadata,
): RegisteredToolConfig {
	const cached = registeredToolConfigCache.get(definition);
	if (cached) return cached;
	const config: RegisteredToolConfig = {
		description: definition.description,
		inputSchema: compactJsonSchema(z.strictObject(definition.inputSchema)),
		annotations: definition.annotations,
	};
	if (definition.outputSchema) {
		config.outputSchema = compactJsonSchema(z.object(definition.outputSchema));
	}
	registeredToolConfigCache.set(definition, config);
	return config;
}

export function registerToolDefinition<
	TSchema extends Record<string, z.ZodTypeAny>,
	TResult,
>(
	server: ToolRegistrar,
	runtime: ToolRuntime,
	definition: ToolDefinition<TSchema, TResult>,
): void;
export function registerToolDefinition(
	server: ToolRegistrar,
	runtime: ToolRuntime,
	definition: UntypedToolDefinition,
): void;
export function registerToolDefinition(
	server: ToolRegistrar,
	runtime: ToolRuntime,
	definition: UntypedToolDefinition,
): void {
	const directHandler = (
		args: RegistrationArgs,
		requestContext?: ToolExecutionContext,
	) =>
		Effect.suspend(() => {
			const scopedRuntime = requestContext
				? runtime.forExecution(requestContext)
				: runtime;
			// Fail inside the Effect so the tagged initialization error reaches
			// the collapse boundary instead of becoming an untyped defect.
			if (!scopedRuntime.client) {
				try {
					scopedRuntime.service(HevyOperationsService);
				} catch {
					return Effect.fail(new ClientNotInitializedError());
				}
			}
			return Effect.catchCause(
				Effect.suspend(() =>
					definition
						.execute(scopedRuntime, args)
						.pipe(
							Effect.map((data) => respond(definition.responseContract, data)),
						),
				),
				(cause) => Effect.failCause(normalizeCoreCause(cause)),
			);
		});
	const handler = runtime.createHandler(directHandler, definition.name, {
		feature: definition.feature,
		kind: definition.kind,
		operation: definition.operation,
	});
	const invalidInputHandler = runtime.createHandler(
		(args: { path: string }) =>
			Effect.fail(new ToolInputValidationError({ path: args.path })),
		definition.name,
		{
			feature: definition.feature,
			kind: definition.kind,
			operation: definition.operation,
		},
	);

	const config = getRegisteredToolConfig(definition);
	server.registerTool(definition.name, config, (args, context) => {
		let parsed: RegistrationArgs;
		try {
			parsed = z.strictObject(definition.inputSchema).parse(args ?? {});
		} catch (error) {
			const path =
				error instanceof z.ZodError
					? error.issues[0]?.path
							?.map((segment) => String(segment))
							.join(".") || "arguments"
					: "arguments";
			if (context) {
				return invalidInputHandler(
					{ path },
					{
						signal: context.mcpReq.signal,
						requestId: String(context.mcpReq.id),
					},
				);
			}
			throw new ToolInputValidationError({ path });
		}
		return handler(
			parsed,
			context
				? {
						signal: context.mcpReq.signal,
						requestId: String(context.mcpReq.id),
					}
				: undefined,
		);
	});
}

import { Cause, Context, Effect } from "effect";
import {
	ApiError,
	ClientNotInitializedError,
	EmptyMeasurementUpdateError,
	NetworkError,
	NotFoundError,
	OperationUnavailableError,
	PaginationMismatchError,
	RateLimitError,
	ToolInputValidationError,
	TrainingSummaryDataError,
	TrainingSummaryValidationError,
	ValidationError,
	WorkoutPayloadError,
	WorkoutPrivacyError,
	type CoreToolError,
} from "../effect-errors.js";
import type { RuntimeValue } from "../utils/type-predicates.js";

type EffectOperation<TArgs extends readonly unknown[], TResult> = {
	readonly effect: (...args: TArgs) => Effect.Effect<TResult, unknown, never>;
};

export function normalizeCoreEffect<A, E>(
	effect: Effect.Effect<A, E, never>,
): Effect.Effect<A, CoreToolError, never> {
	return Effect.catchCause(effect, (cause) =>
		Effect.failCause(normalizeCoreCause(cause)),
	);
}

export function requireOperation<T>(
	operation: T | undefined,
	id: string,
): Effect.Effect<T, OperationUnavailableError, never> {
	return operation === undefined
		? Effect.fail(new OperationUnavailableError({ operation: id }))
		: Effect.succeed(operation);
}

function isCoreToolError(error: RuntimeValue): error is CoreToolError {
	return (
		error instanceof ToolInputValidationError ||
		error instanceof ClientNotInitializedError ||
		error instanceof OperationUnavailableError ||
		error instanceof ApiError ||
		error instanceof NetworkError ||
		error instanceof NotFoundError ||
		error instanceof RateLimitError ||
		error instanceof ValidationError ||
		error instanceof EmptyMeasurementUpdateError ||
		error instanceof PaginationMismatchError ||
		error instanceof TrainingSummaryDataError ||
		error instanceof TrainingSummaryValidationError ||
		error instanceof WorkoutPayloadError ||
		error instanceof WorkoutPrivacyError
	);
}

/**
 * Keep supported upstream tags typed at the core boundary. An operation is
 * external to core and its failure channel is intentionally unknown, so
 * hostile values become defects rather than widening every tool handler.
 */
export function normalizeCoreCause(
	cause: Cause.Cause<unknown>,
): Cause.Cause<CoreToolError> {
	return Cause.fromReasons(
		cause.reasons.map((reason) => {
			if (!Cause.isFailReason(reason)) return reason;
			const normalized = isCoreToolError(reason.error)
				? Cause.makeFailReason(reason.error)
				: Cause.makeDieReason(reason.error);
			return normalized.annotate(Context.makeUnsafe(reason.annotations));
		}),
	);
}

export function operationEffect<TArgs extends readonly unknown[], TResult>(
	operation: Effect.Effect<
		EffectOperation<TArgs, TResult>,
		OperationUnavailableError,
		never
	>,
	...args: TArgs
): Effect.Effect<TResult, CoreToolError, never> {
	// The operation package owns the external Effect seam. Normalize it once,
	// before the value reaches ToolEffectHandler or a tool definition.
	return Effect.flatMap(operation, (resolved) =>
		normalizeCoreEffect(Effect.suspend(() => resolved.effect(...args))),
	);
}

